in_thread do
use_bpm 60
control v,amp: 0.2,amp_slide: 0.175
sleep 25 #6 bars 1 beat
control v,amp: 1,amp_slide: 0.175
sleep 41 #10 bars
control v,amp: 0.2,amp_slide: 0.175
sleep 34.375	 #8 bars 2 beats
control v,amp: 1,amp_slide: 0.1755
sleep 24.125
control v,amp: 0.2,amp_slide: 0.175
sleep 7.75
control v,amp: 1,amp_slide: 0.175
sleep 49.25
control v,amp: 0.2
end


